import{_ as t,c as o,o as p,ah as a}from"./chunks/framework.PvdZnrZd.js";const u=JSON.parse('{"title":"Shopify Custom Apps","description":"Shopify Custom Apps","frontmatter":{"title":"Shopify Custom Apps","description":"Shopify Custom Apps","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/configuration/shopify-custom-apps.md","filePath":"zenith/configuration/shopify-custom-apps.md"}'),n={name:"zenith/configuration/shopify-custom-apps.md"};function i(s,e,r,l,c,h){return p(),o("div",null,[...e[0]||(e[0]=[a('<p>If you are using <a href="https://store.webkul.com/Shopify-Multi-Vendor-Marketplace.html" target="_blank" rel="noreferrer">Multi vendor Marketplace app for Shopify</a>, you can now add a maximum of 5 Custom apps to the Multi-vendor app.</p><p>You can create Shopify Custom Apps and configure them in the app to resolve the API limit issue.</p><h3 id="why-would-you-as-a-merchant-need-this" tabindex="-1">Why would you as a Merchant Need this <a class="header-anchor" href="#why-would-you-as-a-merchant-need-this" aria-label="Permalink to &quot;Why would you as a Merchant Need this&quot;">​</a></h3><p>The <a href="https://webkul.com/blog/product-auction-api-documentation-for-shopify/" target="_blank" rel="noreferrer">Shopify API</a> call limit only allows for two requests per second. So, we get 2 API calls per second from the Shopify end. Sometimes, this API gets exhausted when you deal with larger data.</p><p>Suppose, in case you sync products in bulk, there might be some possibilities that the API gets exhausted, and the complete data won’t get synced properly.</p><p>So, to overcome this API exhaust issue, “Creating Custom apps in the Multi-vendor App is a perfect solution to this problem&quot;.</p><p>In Custom Apps, Shopify provides 3 to 4 API calls per second.</p><p>So, if the merchant lets say, create 1 Custom app on their Shopify store, then per second we will get going to have around 6 API calls per second, which are of course greater than 2 API calls.</p><p>This way, the sync processes would run smoothly.</p><p>Points to be Noted:-</p><ul><li>From here, you can add <strong>a maximum of 5 custom apps</strong> to the multi-vendor app.</li><li>Firstly, you need to <strong>provide the required permissions</strong> in the Shopify private app.</li></ul><h3 id="new-workflow" tabindex="-1">NEW WORKFLOW <a class="header-anchor" href="#new-workflow" aria-label="Permalink to &quot;NEW WORKFLOW&quot;">​</a></h3><h3 id="how-to-create-a-custom-app-in-the-multi-vendor-app" tabindex="-1">How to create a custom app in the Multi-vendor App? <a class="header-anchor" href="#how-to-create-a-custom-app-in-the-multi-vendor-app" aria-label="Permalink to &quot;How to create a custom app in the Multi-vendor App?&quot;">​</a></h3><p>Merchants have to log in to their dev dashboard through <a href="http://dev.shopify.com" target="_blank" rel="noreferrer">dev.shopify.com</a> and then log in to the store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/devlogin-1-1200x545.webp" alt="devlogin"></p><p>After logging in to the dev dashboard with your store, click on the create app button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/createapp-1-1200x545.webp" alt="create app for seller shopify store connector"></p><p>Enter the name and click on the create button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/appname-1200x545.webp" alt="app name "></p><p>You will be redirected to the Create a version page, where you have to fill in the necessary details.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/createaversionspage-1155x1024.webp" alt="create a version page for seller shopify store connector"></p><p>Now, scroll down and fill in the URLs section.</p><p>Follow these steps to find the App URL and Preference URL:-</p><ul><li>You have to log in to the Multivendor admin portal &gt;&gt; go to the <strong>“Shopify Custom Apps”</strong> inside the Configuration menu &gt;&gt; click on the <strong>&quot;Add Shopify Private App&quot;</strong> &gt;&gt; then from the custom app type dropdown select the <strong>&quot;New Custom App&quot;</strong> option &gt;&gt;copy the App URL from there &gt;&gt; paste it into the App URL and Preferences URL block.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/addshopifyprivateapp-1200x545.webp" alt="Shopify Custom App "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/customapptypeappurl-1200x545.webp" alt="copy shopify app url "></p><p>And, paste the link here.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/sellersideurlpaste-1200x545.webp" alt="paste url"></p><p>Now, go back to the <strong>“<strong>Shopify Custom Apps</strong>”</strong> in the admin portal and copy the other URL under the App URL.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/customapptypeotherurl-1200x545.webp" alt="copy shopify other url "></p><p>And, paste it here in the Redirect URL along with the App URL. Only use a comma ( , ) to separate them.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/pasteredirecturl-1200x545.webp" alt="paste other url"></p><h3 id="provide-the-required-permissions-in-the-shopify-private-app" tabindex="-1">Provide the required permissions in the Shopify private app <a class="header-anchor" href="#provide-the-required-permissions-in-the-shopify-private-app" aria-label="Permalink to &quot;Provide the required permissions in the Shopify private app&quot;">​</a></h3><p><strong>Note: Be very specific about the permissions. If it is wrong, no data will be updated as no API will be hit.</strong></p><p>Now, copy these required permissions and paste them into the scope block altogether without any space between them:-</p><p><code>write_assigned_fulfillment_orders,read_assigned_fulfillment_orders,read_fulfillments, write_fulfillments,read_inventory,write_inventory</code></p><p><code>read_locations,read_orders, write_orders,read_products, write_products,read_markets_home,read_customers,write_customers,read_themes,write_themes,read_publications,write_publications</code></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/scopes-1200x545.webp" alt="scope"></p><p>Then, click on Release. A field to enter the version name will appear. You can fill it in or leave it blank; the name will be auto-generated. Click on release.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/versionname-1-1200x545.webp" alt="release version"></p><p>Go back to your dev dashboard, open the app you just created, and navigate to the settings and copy the client ID from the “Credential” section.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/appsettingcredential-1200x544.webp" alt="client id"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/copysecreatkey-1200x545.webp" alt="copy secret key"></p><p>Paste the client ID in the “Api key” block in the <strong>“Shopify Custom App”</strong> inside the Configuration menu at the admin portal.</p><p>Also, copy the “Secret Key” from the “Credential” section and paste it in the &quot;Access Token&quot; block here. You can name the private app whatever you want.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/shopifysecretappformfill-1.webp" alt="shopify secret app form"></p><p>And, click on the “save and install” button at the bottom.</p><p>After you click the <strong>“Save and Install”</strong> button, the system redirects you to your Shopify store to install the app.</p><p>But, if you get an error message like shown in this image below, then follow the process given below the image.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/error-1200x545.webp" alt="error"></p><p>Go to your Shopify partner account &gt;&gt; navigate to “App distribution” &gt;&gt; All apps &gt;&gt; then click on the custom app you created.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/appdistribution-1-1200x545.webp" alt="app distribution"></p><p>From the Overview page, click on the &quot;Choose distribution&quot; Button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/choosedistribution-1200x545.webp" alt="choose distribution"></p><p>Select the &quot;Custom Distribution&quot; option and click Select.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/customdistribution-1200x545.webp" alt="customdistribution"></p><p>After this, you will be redirected to this page, and you have to ignore this page.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/ignore-1200x545.webp" alt="ignore"></p><p>Then, go back to your <strong>Multivendor admin panel</strong> and navigate to the <strong>“Shopify Custom App”</strong> section under the <strong>Configuration</strong> menu.</p><p>After filling in all the required details, click on <strong>“Save &amp; Install”</strong>.<br> Once this is done, the app will be installed successfully.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/installapp-1200x545.webp" alt="install "></p><h3 id="legacy-workflow-old" tabindex="-1">LEGACY WORKFLOW (Old) <a class="header-anchor" href="#legacy-workflow-old" aria-label="Permalink to &quot;LEGACY WORKFLOW (Old)&quot;">​</a></h3><h4 id="how-to-create-custom-apps-in-the-multi-vendor-app" tabindex="-1">How to Create Custom Apps in the Multi-vendor App? <a class="header-anchor" href="#how-to-create-custom-apps-in-the-multi-vendor-app" aria-label="Permalink to &quot;How to Create Custom Apps in the Multi-vendor App?&quot;">​</a></h4><p>To Add a Shopify Custom App, you need to visit the Shopify Admin Panel &gt;&gt; Apps &gt;&gt; Develop apps</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/r1.png" alt="r1"></p><p>Now click on &quot;Create an App&quot;</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/create-app-1200x480.png" alt="create-app"></p><p>Enter the name for the app as per your convenience and then click on &quot;Create&quot;</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/enter-name-1200x526.png" alt="enter-name"></p><p>Click on &quot;Configure Admin API Scope&quot;</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/configure-api-scope-1200x488.png" alt="configure-api-scope"></p><h3 id="provide-the-required-permissions-in-the-shopify-private-app-1" tabindex="-1">Provide the required permissions in the Shopify private app <a class="header-anchor" href="#provide-the-required-permissions-in-the-shopify-private-app-1" aria-label="Permalink to &quot;Provide the required permissions in the Shopify private app&quot;">​</a></h3><ol><li>Product: Write inventory and Read inventory</li><li>Inventory: Write Products and read products</li><li>Order: View or manage orders.</li><li>Location: Read locations</li></ol><p>Then click on &quot;Save&quot;.</p><p><strong>Note: Be very specific about the permissions. If it is wrong, no data will be updated as no API gets hit.</strong></p><p>Select these permissions mentioned below:-</p><p><code>write_assigned_fulfillment_orders,read_assigned_fulfillment_orders,read_fulfillments, write_fulfillments,read_inventory,</code></p><p><code>write_inventory,read_locations,read_orders, write_orders,read_products, write_products,read_markets_home</code>,<code>read_customers,write_customers</code></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/save-issues-1200x507.png" alt="save-issues"></p><p>Click on &quot;Install App&quot;</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/install-app-1200x492.png" alt="install-app"></p><p>Copy the API credential, after that you need to paste this in Mulvendor Private App</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/api-token-1200x775.png" alt="api-token"></p><p>To paste these credentials in the &quot;<strong>Shopify private apps</strong>&quot; section of the Multi-vendor Admin Panel<br> Go to Multivendor Admin Panel&gt;&gt; Configuration&gt;&gt;Shopify private apps&gt;&gt; Click on &quot;Add shopify Private App&quot;</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/Shopify-Private-Apps-Admin-mvm-1200x513.png" alt="Shopify-Private-Apps-Admin-mvm"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/03/name-of-the-app-1200x503.png" alt="name-of-the-app"></p><p><strong>Please Remember</strong> :- In case you want to delete the Custom app on Shopify, firstly you need to delete/disable the same in the app.</p><p>Otherwise, the access token will get expired and no API call gets hit from the Multi-vendor app.</p>',88)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
